import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.WFmvnizL.js";const u=JSON.parse('{"title":"How to Migrate, Backup, and Restore Data?","description":"Migrate, back up, and restore Nezha Monitoring V2 Dashboard data with shutdown, /opt/nezha data directory, permissions, version compatibility, and restoration verification guidance.","frontmatter":{"description":"Migrate, back up, and restore Nezha Monitoring V2 Dashboard data with shutdown, /opt/nezha data directory, permissions, version compatibility, and restoration verification guidance.","outline":"deep"},"headers":[],"relativePath":"en_US/guide/q5.md","filePath":"en_US/guide/q5.md","lastUpdated":1785844584000}'),s={name:"en_US/guide/q5.md"};function i(n,e,d,c,p,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="how-to-migrate-backup-and-restore-data" tabindex="-1">How to Migrate, Backup, and Restore Data? <a class="header-anchor" href="#how-to-migrate-backup-and-restore-data" aria-label="Permalink to &quot;How to Migrate, Backup, and Restore Data?&quot;">​</a></h1><p>Follow these steps to migrate, backup, or restore Nezha Monitoring data:</p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>This page applies only when the source and target are compatible V2 releases. If the data comes from V0 or V1, consult the applicable release and migration notes; do not assume that overwriting files performs a supported cross-generation upgrade.</p></div><ol><li><p><strong>Stop the Dashboard Service</strong><br> Run the one-click script on the old server and select <code>Stop Dashboard</code>.</p></li><li><p><strong>Backup Data</strong><br> Compress the <code>/opt/nezha</code> folder on the old server and copy it to the same location on the new server.</p></li><li><p><strong>Restore Data</strong><br> Extract the <code>/opt/nezha</code> folder to the same path on the new server.</p></li><li><p><strong>Start the Dashboard Service</strong><br> Run the one-click script on the new server and select <code>Start Dashboard</code>.</p></li></ol><hr><h3 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><ul><li>Ensure that the <code>/opt/nezha</code> folder and its contents have the correct permissions and ownership on the new server.</li><li>After the migration is complete, verify its success by accessing the Dashboard interface.</li></ul>',7)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
